bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 41
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';
import pg from 'pg';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {readPrivateToken} from './src/runtime/config.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {videoOfferLink} from './src/telegram/videoInvoiceSales.mjs';
const e=process.env;if(e.VIDEOBOT_DB_NAME!=='videobot'||e.VIDEO_SALE_MODE!=='invoice')throw Error('VIDEO_OWNER_OR_MODE_NOT_VERIFIED');
const p=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:4500});
const net=createCreatorTelegramFetch();
try {
const row=(await p.query("SELECT l.listing_id,l.revision,l.title,l.description,l.price_stars,l.seller_user_id,l.thumbnail_file_id,l.sample_file_id,l.paid_video_file_id,l.status,r.sale_mode,r.status receipt_status FROM videobot_listings l JOIN videobot_post_receipts r ON l.listing_id=r.listing_id WHERE l.listing_id='v26nov24invoice'")).rows[0];
if(!row||row.status!=='published'||row.sale_mode!=='invoice'||row.receipt_status!=='sent'||row.thumbnail_file_id===row.paid_video_file_id||row.sample_file_id===row.paid_video_file_id)throw Error('CURRENT_PRODUCT_NOT_VERIFIED');
const token=readPrivateToken(e.VIDEOBOT_TELEGRAM_TOKEN_FILE);
const api=createTelegramBotApi({token,fetchImpl:net.fetch,timeoutMs:25000});
const sellerId=Number(row.seller_user_id);
if(!Number.isSafeInteger(sellerId)||sellerId<=0)throw Error('SELLER_INVALID');
const chat=await api('getChat',{chat_id:sellerId});
if(chat?.type!=='private'||chat?.id!==sellerId)throw Error('SELLER_PRIVATE_DM_NOT_VERIFIED');
const me=await api('getMe',{});
const url=videoOfferLink(me.username,row.listing_id,Number(row.revision));
const button='⭐ '+row.price_stars+' Starsで本編を購入';
const request={
 chat_id:sellerId,
 rich_message:{blocks:[
  {type:'collage',blocks:[
   {type:'photo',photo:{type:'photo',media:row.thumbnail_file_id,has_spoiler:true}},
   {type:'video',video:{type:'video',media:row.sample_file_id,has_spoiler:true}}
  ]},
  {type:'paragraph',text:row.title+(row.description?'\n'+row.description:'')}
 ]},
 reply_markup:{inline_keyboard:[[{text:button,url}]]}
};
const resp=await net.fetch('https://api.telegram.org/bot'+token+'/sendRichMessage',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(request),signal:AbortSignal.timeout(25000),redirect:'error'});
const data=await resp.json();
const r=data.result,answer=r?.reply_markup?.inline_keyboard?.[0]?.[0];
const blocks=r?.rich_message?.blocks??[];
const collage=Array.isArray(blocks)?blocks.find(x=>x.type==='collage'):null;
const echoTypes=Array.isArray(collage?.blocks)?collage.blocks.map(x=>x.type):[];
const single=r?.message_id>0&&r?.chat?.id===sellerId&&!r?.media_group_id;
const buttonMatches=answer?.url===url&&answer?.text===button;
const valid=data.ok===true&&single&&buttonMatches&&echoTypes.includes('photo')&&echoTypes.includes('video');
let cleanup='NOT_SENT';
if(data.ok===true&&single){
 try{cleanup=(await api('deleteMessage',{chat_id:sellerId,message_id:r.message_id}))===true?'CONFIRMED':'UNKNOWN'}catch{cleanup='FAILED'}
}
let reason='OTHER';
if(data.ok===true)reason='OK';
else {
 const desc=String(data?.description??'').toLowerCase();
 if(desc.includes('method not found'))reason='NO_METHOD';
 else if(desc.includes('rich'))reason='RICH_NOT_SUPPORTED';
 else if(desc.includes('media'))reason='MEDIA_UNAVAILABLE';
 else if(desc.includes('chat not found'))reason='DM_UNAVAILABLE';
 else if(desc.includes('not enough rights'))reason='RIGHTS';
}
console.log('RICH_COLLAGE_PRIVATE_PROBE='+JSON.stringify({http:resp.status,responseOk:data.ok===true,reason,singleMessage:single,albumLikeBlocks:echoTypes,inlinePurchaseButton:buttonMatches,verified:valid,cleanup}));
if(!valid||cleanup!=='CONFIRMED')throw Error('RICH_COLLAGE_PROBE_NOT_VERIFIED');
}finally{await net.close();await p.end();}
NODE
